 static void Audit(){foreach(string q in Q){string prefab=Prop+"/"+q+"/Pachelbel_scenario_HangingIvy_"+q+".prefab";var root=AssetDatabase.LoadAssetAtPath<GameObject>(prefab);var filters=root.GetComponentsInChildren<MeshFilter>(true);if(filters.Length==0||filters.Any(f=>!f.sharedMesh))throw new Exception("Missing ivy mesh after import: "+q);foreach(var f in filters){var mesh=f.sharedMesh;if(!mesh.HasVertexAttribute(VertexAttribute.TexCoord0)||!mesh.HasVertexAttribute(VertexAttribute.TexCoord1))throw new Exception("Missing ivy UV channels: "+q);var mat=f.GetComponent<Renderer>().sharedMaterial;if(!mat||mat.shader.name!="Universal Render Pipeline/Lit"||!mat.IsKeywordEnabled("_ALPHATEST_ON"))throw new Exception("Ivy cutout material not bound: "+q);report.Add(q+" triangles="+Enumerable.Range(0,mesh.subMeshCount).Sum(i=>(long)mesh.GetIndexCount(i)/3)+" vertices="+mesh.vertexCount+" bounds="+mesh.bounds+" mesh="+AssetDatabase.GetAssetPath(mesh));}}File.WriteAllLines(Work+"/migration_report.txt",report);}
 static Bounds ModelBounds(GameObject root){bool first=true;Bounds result=new Bounds();foreach(var f in root.GetComponentsInChildren<MeshFilter>(true)){var b=f.sharedMesh.bounds;for(int i=0;i<8;i++){var v=b.center+Vector3.Scale(b.extents,new Vector3((i&1)==0?-1:1,(i&2)==0?-1:1,(i&4)==0?-1:1));v=f.transform.TransformPoint(v);if(first){result=new Bounds(v,Vector3.zero);first=false;}else result.Encapsulate(v);}}return result;}
 static void AuditModelBounds(){foreach(var q in Q){string original=Work+"/backup/"+Prop+"/"+q+"/Pachelbel_scenario_HangingIvy_"+q+".fbx";string temporary=Shared+"/OriginalBoundsAudit_"+q+".fbx";File.Copy(original,temporary,true);AssetDatabase.ImportAsset(temporary,ImportAssetOptions.ForceSynchronousImport);var oldRoot=AssetDatabase.LoadAssetAtPath<GameObject>(temporary);var newRoot=AssetDatabase.LoadAssetAtPath<GameObject>(Prop+"/"+q+"/Pachelbel_scenario_HangingIvy_"+q+".fbx");var old=ModelBounds(oldRoot);var current=ModelBounds(newRoot);var oldNode=oldRoot.GetComponentInChildren<MeshFilter>().transform;var newNode=newRoot.GetComponentInChildren<MeshFilter>().transform;report.Add(q+" node oldScale="+oldNode.localScale+" newScale="+newNode.localScale+" oldRotation="+oldNode.localEulerAngles+" newRotation="+newNode.localEulerAngles);if(Quaternion.Angle(oldNode.localRotation,newNode.localRotation)>.1f)throw new Exception("Imported ivy node transform differs from original: "+q);AssetDatabase.DeleteAsset(temporary);report.Add(q+" model world bounds before="+old+" after="+current);if((old.size-current.size).magnitude>.01f||(old.center-current.center).magnitude>.01f)throw new Exception("Ivy transformed bounds changed: "+q+" old "+old+" new "+current);}File.WriteAllLines(Work+"/migration_report.txt",report);}
