 camera=new GameObject("BakeCheckCamera").AddComponent<Camera>();camera.transform.position=new Vector3(3,3,-4.7f);camera.transform.LookAt(new Vector3(0,.7f,0));camera.fieldOfView=47;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.11f,.12f,.14f);camera.nearClipPlane=.05f;camera.farClipPlane=30;camera.GetUniversalAdditionalCameraData().renderPostProcessing=false;
