 static void WaitBake(){try{EditorApplication.QueuePlayerLoopUpdate();if(EditorApplication.timeSinceStartup-bakeStart>600)throw new Exception("Ivy check bake timed out");if(!finishing){if(EditorApplication.timeSinceStartup-bakeStart<3||Lightmapping.isRunning)return;report.Add("Alpha bake check seconds="+(EditorApplication.timeSinceStartup-bakeStart));if(LightmapSettings.lightmaps.Length==0)throw new Exception("Ivy bake produced no lightmap");EditorSceneManager.SaveScene(SceneManager.GetActiveScene());AssetDatabase.SaveAssets();finishing=true;readyAt=EditorApplication.timeSinceStartup+8;return;}if(EditorApplication.timeSinceStartup<readyAt||ShaderUtil.anythingCompiling)return;Capture(camera,Work+"/Ivy_AlphaBakeCheck.png");report.Add("Alpha cutout bake scene saved, lightmaps="+LightmapSettings.lightmaps.Length);File.WriteAllLines(Work+"/migration_report.txt",report);EditorApplication.update-=WaitBake;QualitySettings.SetQualityLevel(oldQuality,true);QualitySettings.renderPipeline=oldPipeline;QualitySettings.vSyncCount=oldVsync;MonteverdiLightingLab.Start();File.WriteAllText(Work+"/ready.txt","ready");}catch(Exception e){Fail(e);}}
 static void Capture(Camera cam,string path){var rt=new RenderTexture(1600,1000,24,RenderTextureFormat.ARGB32){antiAliasing=4};rt.Create();cam.targetTexture=rt;for(int i=0;i<3;i++)cam.Render();var prev=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(rt.width,rt.height,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);image.Apply();File.WriteAllBytes(path,image.EncodeToPNG());RenderTexture.active=prev;cam.targetTexture=null;Object.DestroyImmediate(image);rt.Release();Object.DestroyImmediate(rt);}
